<?php
require_once __DIR__.'/../../config/config.php';require_roles(['ADMIN','HR']);$pdo=db();$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$id=(int)($_POST['id']??0);$values=[(int)$_POST['document_type_id'],trim($_POST['name']),trim($_POST['code']),post_value('description'),trim($_POST['content']),$_SESSION['user_id']];if(!$values[1]||!$values[2]||!$values[4])throw new InvalidArgumentException('Required fields missing.');if($id){$pdo->prepare('UPDATE document_templates SET document_type_id=?,name=?,code=?,description=?,content=? WHERE id=?')->execute([...array_slice($values,0,5),$id]);audit('TEMPLATE_UPDATED','document_templates',$id);}else{$pdo->prepare('INSERT INTO document_templates (document_type_id,name,code,description,content,created_by) VALUES (?,?,?,?,?,?)')->execute($values);audit('TEMPLATE_CREATED','document_templates',(int)$pdo->lastInsertId());}flash('success','Template saved.');redirect('admin/document-templates/index.php');}catch(Throwable $exception){$error='Template code must be unique and all required fields must be filled.';}}$types=$pdo->query('SELECT id,name FROM document_types WHERE is_active=1 ORDER BY name')->fetchAll();$templates=$pdo->query('SELECT t.*,d.name type_name FROM document_templates t JOIN document_types d ON d.id=t.document_type_id ORDER BY t.name')->fetchAll();$pageTitle='Document templates';require __DIR__.'/../../includes/header.php';?><div class="flex justify-between mb-7"><div><h1 class="font-display text-3xl font-bold">Document templates</h1><p class="text-sm text-slate-500 mt-1">Safe placeholders: employee ID, name, position, department, branch, date hired.</p></div></div><div class="grid xl:grid-cols-[1fr_440px] gap-6"><section class="bg-white border rounded-xl p-6 space-y-4"><?php foreach($templates as $template):?><article class="border-b pb-4"><div class="flex justify-between"><b><?=e($template['name'])?></b><span class="text-xs text-teal-700"><?=e($template['type_name'])?></span></div><p class="text-xs text-slate-400 mt-1"><?=e($template['code'])?></p><pre class="mt-2 whitespace-pre-wrap text-xs text-slate-600"><?=e($template['content'])?></pre></article><?php endforeach;?></section><form method="post" class="bg-white border rounded-xl p-6 space-y-3"><?= csrf_field() ?><h2 class="font-display text-xl font-bold">Create template</h2><select name="document_type_id" required class="field"><option value="">Document type</option><?php foreach($types as $type):?><option value="<?=$type['id']?>"><?=e($type['name'])?></option><?php endforeach;?></select><input name="name" required placeholder="Template name" class="field"><input name="code" required placeholder="Unique code" class="field"><textarea name="description" placeholder="Description" class="field"></textarea><textarea name="content" required rows="8" placeholder="Use {{employee.first_name}} and supported placeholders" class="field"></textarea><button class="rounded-lg bg-teal-700 px-4 py-3 text-sm font-bold text-white">Save template</button></form></div><?php require __DIR__.'/../../includes/footer.php';